  WHERE NOT EXISTS (
    SELECT 1 FROM information_schema.columns k
    WHERE k.table_schema = 'public' AND k.table_name = r.t AND k.column_name = r.c
  );
  IF missing IS NOT NULL THEN
    RAISE EXCEPTION 'Na tej bazie brakuje kolumn (najpierw wdróż zaległe migracje): %', missing;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM producer WHERE id = '251bc664-bb50-4543-b893-c9a28a926bca') THEN
    RAISE EXCEPTION 'Brak producenta Cocomodule (251bc664-bb50-4543-b893-c9a28a926bca) na tej bazie, przerywam';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM users WHERE id = '73d11d36-1b8b-4c39-803a-8cbb1943aed0') THEN
